class entity;

class SoundScriptManager {
public:
    enum EventType { WAVE_EVENT = 21, COMP_EVENT = 23 };
    void clearEvents();
    void addEvent(EventType type, float time, entity *ent);
};

class game {
    char pad0[0x74];
public:
    int mode;
private:
    char pad1[0x38];
public:
    int submode;
    bool is_competition_level();
};

struct beach_object {
    beach_object *next;
    char pad04[4];
    int schedule;
    char pad0c[4];
    int spawned;
    char pad14[4];
    int active;
    int never_despawn;
    char pad20[0x18];
    struct vtable_t {
        char pad00[0x18];
        short adjustment;
        short reserved;
        void (*despawn)(void *);
    } *vtable;
};

struct BeachData {
    char pad00[0xC4];
    float wave_duration;
    char padC8[0x14];
};

struct CareerData {
    char pad00[0x150];
    float wave_duration;
    char pad154[0xB8];
};

extern SoundScriptManager *sound_script_mgr;
extern game *g_game_ptr;
extern BeachData BeachDataArray[];
extern CareerData CareerDataArray[];
extern int WAVE_GetScheduleIndex();

__asm__(".equ sound_script_mgr, 0x0045B4A0");
__asm__(".equ g_game_ptr, 0x0045AC64");
__asm__(".equ BeachDataArray, 0x0041ECA0");
__asm__(".equ CareerDataArray, 0x0042C198");
__asm__(".equ clearEvents__18SoundScriptManager, 0x0031BEC0");
__asm__(".equ addEvent__18SoundScriptManager9EventTypefP6entity, 0x0031C580");
__asm__(".equ is_competition_level__4game, 0x0027AAA8");
__asm__(".equ WAVE_GetScheduleIndex__Fv, 0x0037D8B8");

class beach {
    char pad00[0x2C4];
    beach_object *my_objects;
    int current_breakmap;
public:
    void OnNewWave();
};

void beach::OnNewWave()
{
    sound_script_mgr->clearEvents();

    if (g_game_ptr->mode == 0 || g_game_ptr->mode == 2 ||
        g_game_ptr->submode == 2) {
        float duration;
        if (g_game_ptr->mode == 0)
            duration = BeachDataArray[*((int *)g_game_ptr + 137)].wave_duration;
        else
            duration = CareerDataArray[*((int *)g_game_ptr + 138)].wave_duration;

        int end_time = (int)duration;
        if (end_time < 11) {
            int event_time = end_time - 2;
            for (int i = 0; i < 9; ++i)
                sound_script_mgr->addEvent(SoundScriptManager::WAVE_EVENT,
                                           (float)(event_time - i), 0);

            if (g_game_ptr->is_competition_level() && g_game_ptr->mode == 0)
                sound_script_mgr->addEvent(SoundScriptManager::COMP_EVENT,
                                           (float)(end_time - 1), 0);
            else
                sound_script_mgr->addEvent(SoundScriptManager::WAVE_EVENT,
                                           (float)(end_time - 1), 0);
        } else {
            return;
        }
    }

    current_breakmap = WAVE_GetScheduleIndex();
    for (beach_object *object = my_objects; object; object = object->next) {
        if (!object->never_despawn && object->spawned) {
            beach_object::vtable_t *vtable = object->vtable;
            vtable->despawn((char *)object + vtable->adjustment);
        }
        object->active = object->schedule == current_breakmap ||
                         object->schedule == -1;
    }
}
